create table telemetry_readings (captured_at datetime(6) not null, created_at datetime(6) not null, id bigint not null auto_increment, level_amount float(53) not null, organization_id bigint, received_at datetime(6) not null, schema_version integer not null, sequence_number bigint not null, tank_id bigint, updated_at datetime(6) not null, channel varchar(60) not null, device_id varchar(120) not null, level_unit varchar(20) not null, quality VARCHAR(20) not null, quarantine_reason varchar(80), primary key (id)) engine=InnoDB;
alter table telemetry_readings add constraint uk_telemetry_readings_device_sequence unique (device_id, channel, sequence_number);
